//! Golden values generated by encoding/json from copies of engine-go/types.go.
use engine::types::*;

#[test]
fn types_match_go_json() {
    let golden: Vec<serde_json::Value> = include_str!("go_json_golden.jsonl")
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    let stats = StatsResponse {
        download_speed: 0,
        upload_speed: 0,
        progress: 0.0,
        ratio: 0.0,
        torrents: 0,
        ctl_port: 0,
        stream_port: 0,
        path: String::new(),
        payload_transfers_allowed: false,
        listen_port: 0,
        holepunch: Default::default(),
    };
    // `holepunch` (BEP 55 counters) is a Rust-engine extension the Go
    // golden does not have; check it here and compare the rest to Go.
    let mut stats = serde_json::to_value(stats).unwrap();
    assert_eq!(
        stats.as_object_mut().unwrap().remove("holepunch").unwrap(),
        serde_json::json!({
            "rendezvousSent": 0,
            "connectReceived": 0,
            "relayedForOthers": 0,
            "errorsReceived": 0,
            "punchDialsAttempted": 0,
            "punchDialsSucceeded": 0,
        })
    );
    let values = [
        (0, stats),
        (
            1,
            serde_json::to_value(AddRequest {
                torrent_id: String::new(),
                prepare: false,
                torrent_data: Some(String::new()),
            })
            .unwrap(),
        ),
        (
            2,
            serde_json::to_value(AddResponse {
                id: String::new(),
                info_hash: None,
            })
            .unwrap(),
        ),
        (
            3,
            serde_json::to_value(PlayRequest {
                file_index: Some(0),
                ..Default::default()
            })
            .unwrap(),
        ),
        (6, serde_json::to_value(SettingsRequest::default()).unwrap()),
        (7, serde_json::to_value(SeekStats::default()).unwrap()),
        (
            8,
            serde_json::to_value(TrackerView {
                url: String::new(),
                tier: 0,
                status: String::new(),
                message: Some(String::new()),
                original: false,
            })
            .unwrap(),
        ),
        (
            9,
            serde_json::to_value(OkResponse {
                ok: false,
                id: Some(String::new()),
            })
            .unwrap(),
        ),
    ];
    for (index, actual) in values {
        assert_eq!(actual, golden[index], "Go golden case {index}");
    }
}

#[test]
fn bypass_distinguishes_nil_and_empty_coverage() {
    let mut value = BypassStatus {
        enabled: false,
        active: false,
        mode: "off".into(),
        coverage: None,
        error: None,
    };
    assert_eq!(
        serde_json::to_value(&value).unwrap()["coverage"],
        serde_json::Value::Null
    );
    assert_eq!(
        serde_json::to_value(&value).unwrap()["error"],
        serde_json::Value::Null
    );
    value.coverage = Some(vec![]);
    assert_eq!(
        serde_json::to_value(&value).unwrap()["coverage"],
        serde_json::json!([])
    );
}

#[test]
fn configure_nil_slices_match_go_json() {
    let golden: serde_json::Value = serde_json::from_str(include_str!("go_json_golden.jsonl").lines().nth(4).unwrap()).unwrap();
    let request: ConfigureRequest = serde_json::from_value(golden.clone()).expect("Go nil descriptors/selected must deserialize");
    assert_eq!(serde_json::to_value(request).unwrap(), golden);
}

#[test]
fn select_nil_slices_match_go_json() {
    let golden: serde_json::Value = serde_json::from_str(include_str!("go_json_golden.jsonl").lines().nth(5).unwrap()).unwrap();
    let request: SelectRequest = serde_json::from_value(golden.clone()).expect("Go nil selected must deserialize");
    assert_eq!(serde_json::to_value(request).unwrap(), golden);
}

/// Field names and values the Android app reads for the swarm line
/// (`EngineClient.parseConnections`: `source`, `bittorrentVersion`;
/// `PEER_SOURCE_HOLEPUNCH = "C"`; `isBt2` is `bittorrentVersion == "v2"`).
#[test]
fn peer_connection_view_bt2_and_holepunch_fields_match_android() {
    let view = PeerConnectionView {
        address: "203.0.113.1:6881".into(),
        transport: "uTP".into(),
        client: String::new(),
        downloaded: 0,
        uploaded: 0,
        country: None,
        peer_choking: None,
        am_interested: None,
        pending_requests: None,
        peer_completion: None,
        download_rate: None,
        rtt_ms: None,
        pipeline_limit: None,
        nominal_max_requests: None,
        peer_max_requests: None,
        peak_requests: None,
        source: Some(wt_core::PeerSource::UtHolepunch.code().into()),
        bittorrent_version: Some("v2".into()),
    };
    let json = serde_json::to_value(&view).unwrap();
    assert_eq!(json["source"], "C");
    assert_eq!(json["bittorrentVersion"], "v2");
}

/// Per-torrent holepunch block on `/connections/{id}` (UI should prefer this
/// over client-wide `/stats.holepunch`).
#[test]
fn connections_response_includes_per_torrent_holepunch() {
    let resp = ConnectionsResponse {
        id: "t1".into(),
        paused: false,
        peers: vec![],
        holepunch: wt_core::holepunch::HolepunchStats {
            rendezvous_sent: 13,
            connect_received: 2,
            relayed_for_others: 0,
            errors_received: 11,
            punch_dials_attempted: 2,
            punch_dials_succeeded: 0,
        },
        diagnostics: None,
    };
    let json = serde_json::to_value(&resp).unwrap();
    assert_eq!(
        json["holepunch"],
        serde_json::json!({
            "rendezvousSent": 13,
            "connectReceived": 2,
            "relayedForOthers": 0,
            "errorsReceived": 11,
            "punchDialsAttempted": 2,
            "punchDialsSucceeded": 0,
        })
    );
}
